function compareScreen(){
 const rows=C.roster(collectionRows()),selected=compareKeys.map(key=>rows.find(r=>r.key===key)).filter(Boolean);if(selected.length!==2){screen='archives';return archivesScreen();}
 const [a,b]=selected,common=[['전성기 능력',a.prime.ovr,b.prime.ovr],['출전',a.stats.apps,b.stats.apps],['평균 평점',a.stats.rating.toFixed(2),b.stats.rating.toFixed(2)],['개인 수상',a.g.awards.length,b.g.awards.length],['팀 우승',a.g.trophies.length,b.g.trophies.length]];
 return '<main class="content clubhouse-page">'+title('COMPARE','선수 비교','능력치는 저장된 전성기 기준, 경기 성적은 커리어 통산입니다.')+'<div class="compare-identities">'+selected.map(r=>'<div style="'+themedStyle(r.prime.clubId)+'">'+clubIcon(r.prime.clubId,r.prime.club)+'<b>'+esc(r.g.player.name)+'</b><span>'+r.g.player.pos+' · '+esc(r.prime.club)+'</span></div>').join('')+'</div><section class="card compare-table"><table><caption>통산 기록</caption><tbody>'+common.map(([label,x,y])=>'<tr><td>'+x+'</td><th>'+label+'</th><td>'+y+'</td></tr>').join('')+'</tbody></table></section><section class="card compare-table"><table><caption>포지션별 대표 성적</caption><tbody>'+[['골','goals'],['도움','assists'],['키패스','keyPasses'],['태클','tackles'],['가로채기','interceptions'],['선방','saves'],['무실점','clean']].map(([label,id])=>'<tr><td>'+a.stats[id]+'</td><th>'+label+'</th><td>'+b.stats[id]+'</td></tr>').join('')+'</tbody></table></section><section class="card compare-table"><table><caption>전성기 세부 능력치</caption><tbody>'+Object.values(E.ATTR).flatMap(group=>group.items).map(([id,label])=>{const x=E.activeAttributes(a.g.player).includes(id)?Math.floor(a.prime.details[id]):null,y=E.activeAttributes(b.g.player).includes(id)?Math.floor(b.prime.details[id]):null;return '<tr><td class="'+(x!==null&&y!==null&&x>y?'compare-better':'')+'">'+(x??'—')+'</td><th>'+label+'</th><td class="'+(x!==null&&y!==null&&y>x?'compare-better':'')+'">'+(y??'—')+'</td></tr>';}).join('')+'</tbody></table><p class="help">해당 포지션에서 사용하지 않는 능력치는 —로 표시합니다.</p></section>'+btn('← 선수 보관','collection-back','','outline full')+'</main>';
}
